// N8N Code node (Run Once for All Items) — normaliza os clientes recebidos no Webhook.
const clientes = $('Webhook').first().json.body.clientes || [];

const parseSaldo = s => Number(String(s).replace(/[^\d,]/g, '').replace(',', '.')) || 0;

return clientes.map(c => ({
  json: {
    nome: String(c.nome || '').trim(),
    email: String(c.email || '').trim(),
    perfil: String(c.perfil || '').trim(),
    saldo: parseSaldo(c.saldo),
  },
}));

// N8N Code node (Run Once for All Items) — transforma o CSV de investimentos em itens.
const csv = $input.first().json.data || '';

const [cabecalho, ...linhas] = csv.trim().split(/\r?\n/);
const colunas = cabecalho.split(',').map(c => c.trim());

return linhas.filter(Boolean).map(l => {
  const v = l.split(',');
  const o = {};
  colunas.forEach((c, i) => (o[c] = (v[i] || '').trim()));
  return {
    json: {
      perfil: o.perfil,
      produto: o.produto,
      minimo: Number(o.minimo),
      rentabilidade: o.rentabilidade,
    },
  };
});

// N8N Code node (Run Once for All Items) — a saída do Merge tem uma linha por cliente x produto;
// aqui ela vira uma linha por cliente, com a tabela de opções e o prompt para o modelo.
const brl = n =>
  'R$ ' + Number(n).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');

const grupos = new Map();
for (const { json: r } of $input.all()) {
  const chave = `${r.email}|${r.nome}`;
  if (!grupos.has(chave)) {
    grupos.set(chave, { nome: r.nome, email: r.email, perfil: r.perfil, saldo: r.saldo, opcoes: [] });
  }
  if (r.produto) {
    grupos.get(chave).opcoes.push({
      produto: r.produto,
      minimo: Number(r.minimo),
      rentabilidade: r.rentabilidade,
    });
  }
}

return [...grupos.values()].map(g => {
  const elegiveis = g.opcoes.filter(o => o.minimo <= g.saldo);
  const primeiroNome = g.nome.split(' ')[0];

  const tabela = [
    '| Produto | Mínimo | Rentabilidade | Elegível |',
    '| --- | --- | --- | --- |',
    ...g.opcoes.map(
      o => `| ${o.produto} | ${brl(o.minimo)} | ${o.rentabilidade} | ${o.minimo <= g.saldo ? 'Sim' : 'Não'} |`
    ),
  ].join('\n');

  const prompt =
    `Cliente: ${g.nome}\n` +
    `Perfil de investidor: ${g.perfil}\n` +
    `Saldo disponível: ${brl(g.saldo)}\n` +
    `Situação: ${
      elegiveis.length
        ? `saldo cobre o mínimo de ${elegiveis.length} opção(ões)`
        : 'saldo abaixo do mínimo de todas as opções do perfil'
    }\n\n` +
    `Opções de investimento do perfil:\n${tabela}`;

  return {
    json: {
      nome: g.nome,
      primeiro_nome: primeiroNome,
      email: g.email,
      perfil: g.perfil,
      saldo: g.saldo,
      saldo_formatado: brl(g.saldo),
      opcoes_elegiveis: elegiveis.map(o => o.produto),
      tabela_opcoes: tabela,
      prompt,
    },
  };
});

// N8N Code node (Run Once for All Items) — normaliza o e-mail e a mensagem gerada pelo modelo.
// O nó do modelo não repassa os dados do cliente; os itens são casados pela posição.
const clientes = $('Code - Normalizar Tabela').all();
const respostas = $input.all();

const emailRegex = /^[a-z0-9._%+-]+@[a-z0-9-]+(\.[a-z0-9-]+)*\.[a-z]{2,}$/;

const extrairTexto = j => {
  if (!j || j.error) return '';
  if (typeof j.output_text === 'string') return j.output_text;
  if (typeof j.text === 'string') return j.text;
  if (typeof j.output === 'string') return j.output;
  const partes = (Array.isArray(j.output) ? j.output : [])
    .flatMap(o => o.content || [])
    .map(c => c.text || '')
    .filter(Boolean);
  return partes.join('\n');
};

return clientes.map(({ json: c }, i) => {
  const email = String(c.email || '').trim().toLowerCase();
  const gerada = extrairTexto(respostas[i]?.json).replace(/[*_#`>]/g, '').trim();

  const padrao =
    `Olá, ${c.primeiro_nome}! Com seu perfil ${c.perfil} e saldo de ${c.saldo_formatado}, ` +
    `as opções disponíveis para você são: ${c.opcoes_elegiveis.join(', ') || 'nenhuma no momento'}.`;

  const corpo = gerada || padrao;

  return {
    json: {
      ...c,
      email,
      email_valido: email.length <= 254 && emailRegex.test(email),
      mensagem_origem: gerada ? 'ia' : 'modelo_padrao',
      assunto: `${c.primeiro_nome}, uma sugestão de investimento para o seu perfil ${c.perfil}`,
      corpo,
    },
  };
});
